"""Diagnose raw request timing without changing any scored request or metric."""
from pathlib import Path
import json,hashlib,datetime,statistics,math
O=Path(__file__).resolve().parent
source=json.loads((O/'tail-analysis.json').read_text());out=[]
for r in source['runs']:
 export=Path(r['export']);e=json.loads(export.read_text());journal=export.with_name('profile_export.jsonl');all_rows=[json.loads(line) for line in journal.open()];rows=[x for x in all_rows if x['metadata'].get('benchmark_phase')=='profiling'];t0=min(x['metadata']['request_start_ns'] for x in rows);warm=[x for x in all_rows if x['metadata'].get('benchmark_phase')=='warmup'];overlap=[x for x in warm if x['metadata']['request_start_ns']<t0<x['metadata']['request_end_ns']]
 phase=e['input_config']['phases'];n=next(x['concurrency'] for x in phase if x['kind']=='profiling');run=next(x for x in export.parents if (x/'config.json').exists());job=run.name
 initial=[x for x in rows if (x['metadata']['request_start_ns']-t0)/1e9<1];later=[x for x in rows if (x['metadata']['request_start_ns']-t0)/1e9>=1];bins=[]
 for start,end in [(0,1),(1,30),(30,60),(60,90),(90,float('inf'))]:
  bucket=[x for x in rows if start<=(x['metadata']['request_start_ns']-t0)/1e9<end];badttft=sum(x['metrics']['time_to_first_token']['value']>3000 for x in bucket);baditl=sum(x['metrics']['inter_token_latency']['value']>20 for x in bucket);bins.append(dict(start_s=start,end_s=None if math.isinf(end) else end,requests=len(bucket),ttft_failures=badttft,itl_failures=baditl))
 bad=[x for x in r['failed_requests'] if x['type'] in ['ttft_only','both']];itl_bad=[x for x in r['failed_requests'] if x['type'] in ['itl_only','both']]
 good=e['good_request_count']['avg'];total=e['request_count']['avg'];rate=e['goodput']['avg']*200
 out.append(dict(job=job,concurrency=n,export=str(export),raw_sha256=hashlib.sha256(journal.read_bytes()).hexdigest(),raw_reconciled=r['all_counts_match_official_summary'],classifications=r['classifications'],initial_requests_first_second=len(initial),warmup_requests_overlapping_first_profiling_start=len(overlap),ttft_failed_start_range_s=r['ttft_failed_start_range_s'],ttft_failed_ms_range=[min(x['ttft_ms'] for x in bad),max(x['ttft_ms'] for x in bad)] if bad else None,itl_failed_start_times_s=[x['start_relative_s'] for x in itl_bad],start_time_bins=bins,observed_good_tokens_s=rate,zero_violation_counterfactual_good_tokens_s=rate*total/good,relative_headroom_percent_if_all_requests_pass=100*(total/good-1)))
(O/'burst-analysis.json').write_text(json.dumps(dict(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),runs=out,caveat='Request timing associations only. No server causal attribution. Counterfactual holds observed total request rate fixed and is not a speedup prediction.'),indent=2)+'\n')
lines=['# Where the remaining latency failures occur', '', 'All counts below come from scored profiling requests in the raw AIPerf journals and reconcile with their official exports. Warmup traffic is excluded from the score. No request is removed and no benchmark threshold is changed.', '', '| Job / platform | N | Requests | TTFT-only misses | ITL-only misses | TTFT-miss request starts after phase start |', '|---|---:|---:|---:|---:|---|']
for r in out:
 lo,hi=r['ttft_failed_start_range_s'];lines.append('| {} / {} | {} | {} | {} | {} | {:.4f}–{:.4f} s |'.format(r['job'],'H100' if '.pbs' in r['job'] else 'H200',r['concurrency'],sum(r['classifications'].values()),r['classifications']['ttft_only'],r['classifications']['itl_only'],lo,hi))
lines+=['', '## Findings', '', 'In all four runs, every TTFT failure belongs to the initial simultaneous request burst. These requests start within roughly 30 milliseconds of the first scored request. All H200 request mean ITLs pass the 20 ms limit, including those whose TTFT fails. The H100 control also has three ITL-only misses, whose exact timing is retained in burst-analysis.json.', '', 'The initial first-second request counts match N: 56, 56, 58 and 50. No recorded warmup request overlaps the first profiling request in these journals. This rejects the proposed explanation of outstanding warmup traffic doubling decode load for these observations. It does not exclude hidden server state or prove a unique queueing cause.', '', 'The pattern is consistent with a cold arrival burst waiting for prompt processing, routing or KV delivery. It is not evidence that steady-state decode ITL is currently failing on H200. Worker-level aligned tracing would be needed to attribute the wait to one component.', '', '## How large is this opportunity?', '', '| Job | Observed good tokens/s | If all requests passed at the same observed total rate | Relative headroom |', '|---|---:|---:|---:|']
for r in out:lines.append('| {} | {:.3f} | {:.3f} | {:.3f}% |'.format(r['job'],r['observed_good_tokens_s'],r['zero_violation_counterfactual_good_tokens_s'],r['relative_headroom_percent_if_all_requests_pass']))
lines+=['', 'This arithmetic holds total request throughput fixed. It is not a prediction that a configuration change can remove every miss, and faster total service could change both numerator and duration. For the latest H200 candidate, eliminating all existing misses at unchanged total throughput offers only about 1.2%; a larger gain requires improved total service as well.', '', '## Next conditional candidate', '', 'A larger prefill chunk with the new DeepGEMM runner is a bounded hypothesis: larger prompt batches may change MoE kernel efficiency. The old auto-runner chunk8192 trial lost versus chunk4096, so do not claim an existing improvement or repeat it unchanged. Prepare DeepGEMM plus chunk8192 at N56, changing only chunk size versus the DeepGEMM candidate. First review the pending independent N56 confirmation and graph ablation; submit only when a queue slot opens and the results still justify it. One bounded test, full protocol and quality gates, then close the branch on no useful gain.', '', 'Do not drop initial requests, delay traffic based on benchmark phase, alter the official seed or warmup, or redefine the score. Generic service improvements must handle burst arrivals while retaining the same benchmark and output checks.', '', '## Reproduction', '', '- Run analyze-burst.py after the saved tail-analysis.json is available.', '- burst-analysis.json contains source paths, raw hashes, timing bins and exact counterfactual arithmetic.', '- The parent analysis is ../analyze-latency-failures.py; its raw counts reconcile with the benchmark exports.']
(O/'RESULTS.md').write_text('\n'.join(lines)+'\n');print('\n'.join(lines[:12]))
